use serde::{Serialize,Deserialize};
use std::{path::{Path,PathBuf},fs::{self,OpenOptions},os::windows::{fs::{MetadataExt,OpenOptionsExt},io::AsRawHandle}};
use windows_sys::Win32::Storage::FileSystem::{SetFileInformationByHandle,FileDispositionInfo,FILE_DISPOSITION_INFO};
#[derive(Clone,Serialize,Deserialize)]pub struct Candidate{pub path:String,pub size:u64,pub modified:u64}
fn supported_name(path:&Path)->bool{path.extension().and_then(|e|e.to_str()).is_some_and(|e|["tmp","temp","log","etl","dmp"].contains(&e.to_ascii_lowercase().as_str()))}
fn root()->Result<PathBuf,String>{let local=std::env::var_os("LOCALAPPDATA").ok_or("LOCALAPPDATA ausente")?;let p=PathBuf::from(local).join("Temp");if fs::symlink_metadata(&p).map_err(|e|e.to_string())?.file_attributes()&0x400!=0{return Err("A pasta temporária é um reparse point; limpeza bloqueada".into())}p.canonicalize().map_err(|e|e.to_string())}
fn safe_metadata(p:&Path)->Option<fs::Metadata>{if !supported_name(p){return None}let m=fs::symlink_metadata(p).ok()?;if !m.is_file()||m.file_attributes()&0x400!=0{return None}Some(m)}
pub fn scan()->Result<Vec<Candidate>,String>{let root=root()?;let mut rows=Vec::new();for entry in fs::read_dir(&root).map_err(|e|e.to_string())?.take(10000).flatten(){let p=entry.path();if let Some(m)=safe_metadata(&p){let modified=m.last_write_time();let age=m.modified().ok().and_then(|t|t.elapsed().ok()).map(|d|d.as_secs()).unwrap_or(0);if age>=7*86400{rows.push(Candidate{path:p.to_string_lossy().to_string(),size:m.len(),modified})}}}Ok(rows)}
pub fn delete(selected:Vec<Candidate>)->Result<serde_json::Value,String>{if selected.len()>10000{return Err("Seleção demasiado grande".into())}let root=root()?;let mut results=Vec::new();for file in selected{let p=Path::new(&file.path);let result=(||->Result<(),String>{if p.parent()!=Some(root.as_path()){return Err("Caminho fora da pasta permitida".into())}let m=safe_metadata(p).ok_or("Ficheiro irregular, link ou reparse point")?;if m.len()!=file.size||m.last_write_time()!=file.modified{return Err("O ficheiro foi alterado após a análise".into())}if m.modified().map_err(|e|e.to_string())?.elapsed().map_err(|e|e.to_string())?.as_secs()<7*86400{return Err("Ficheiro recente protegido".into())}let h=OpenOptions::new().access_mode(0x10000|0x80).share_mode(0).custom_flags(0x00200000).open(p).map_err(|e|format!("Em utilização ou sem permissão: {e}"))?;let hm=h.metadata().map_err(|e|e.to_string())?;if hm.file_attributes()&0x400!=0||hm.len()!=file.size||hm.last_write_time()!=file.modified{return Err("A identidade do ficheiro mudou".into())}let info=FILE_DISPOSITION_INFO{DeleteFile:1};let ok=unsafe{SetFileInformationByHandle(h.as_raw_handle() as _,FileDispositionInfo,&info as *const _ as _,std::mem::size_of::<FILE_DISPOSITION_INFO>() as u32)};if ok==0{return Err(std::io::Error::last_os_error().to_string())}drop(h);Ok(())})();results.push(serde_json::json!({"path":file.path,"size":file.size,"deleted":result.is_ok(),"error":result.err()}));}Ok(serde_json::json!(results))}
